sys_script_client.script:
function onLoad() { 
    // Define which fields to make read-only based on user type
    var includedFields;
    var integrationUserList = g_scratchpad.integrationUsers; // List of integration users

    // Check if the current user is an integration user
    if (integrationUserList.split(',').includes(g_scratchpad.openedBy)) {
        // For integration users, these fields will be read-only
        includedFields = [
            'subject','u_sender','u_receiver','u_reference_number',
            'u_employer_id','u_member_id','original_received_date',
            'query_id','state','assignment_group','assigned_to'
        ];
    } else {
        // For manual users, only these fields will be read-only
        includedFields = ['state','assignment_group','assigned_to','query_id'];
    }

    // Set only the included fields to read-only
    includedFields.forEach(function(field) {
        g_form.setReadOnly(field, true);
    });

    // If user has ops_admin role, make assigned_to editable
    if (g_user.hasRole('x_hsb11_mss_trus_0.ops_admin')) {
        g_form.setReadOnly('assigned_to', false);
    }
}
